            rc = tgRoleCode(ar, cur);
            ent = Pdflex.plNameEntry(ar, cur);
            if (rc != 0) {
                how = 0;
                if (steps > 0) {
                    how = 1;
                }
                if ((steps == 0) && (rm != 0)) {
                    if (Pdflex.plDictFind(ar, rm, ent) != 0) {
                        how = 5;
                    }
                }
                return ((rc % 256) + (how * 256)) + ((rc / 256) * 65536);
            }
            if (rm == 0) {
                return 512;
            }
            v = Pdflex.plDictFind(ar, rm, ent);
            if (v == 0) {
                return 512;
            }
            next = Pdfdoc.pdResolve(src, ar, dc, a, b, st, v);
            if (next == 0) {
                return 512;
            }
            if (Pdflex.plKindOf(ar, next) != 4) {
                return 512;
            }
            cur = next;
            steps += 1;
